def is_triangle_free(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

def is_maximal(n, edges):
    # Check if adding any missing edge creates a triangle
    all_edges = set()
    for u, v in edges:
        all_edges.add(tuple(sorted((u, v))))

    for i in range(n):
        for j in range(i + 1, n):
            if tuple(sorted((i, j))) not in all_edges:
                # Try adding this edge
                new_edges = edges + [(i, j)]
                if is_triangle_free(n, new_edges):
                    return False
    return True

# Generate K_{5,5}
edges = []
for i in range(5):
    for j in range(5, 10):
        edges.append((i, j))

print(f"Is triangle-free: {is_triangle_free(10, edges)}")
print(f"Is maximal: {is_maximal(10, edges)}")
